async function undoPlanning(ack={}){const button=document.getElementById('dp-undo-planning');if(button)button.disabled=true;try{const saved=await command('undo-planning',{undoId:planningUndoTokens.at(-1),...ack});planningUndoTokens.pop();state.revision=saved.revision;const r=saved.result;state.allocations=state.allocations.filter(a=>!r.allocationIds.includes(a.id)).concat(r.allocations);state.requests=state.requests.filter(a=>!r.requestIds.includes(a.id)).concat(r.requests);for(const o of Object.values(state.obligations)){const list=state.allocations.filter(a=>a.obligationId===o.id),assigned=list.reduce((n,a)=>n+total(a),0);state.coverage[o.id]={required:o.sizeUnits,assigned,missing:o.sizeUnits==null?null:Math.max(0,o.sizeUnits-assigned),excess:o.sizeUnits==null?null:Math.max(0,assigned-o.sizeUnits)};o.displayStatus=list.length?(state.coverage[o.id].missing===0&&list.every(a=>a.status==='confirmed')?'برنامهٔ قطعی':'دارای برنامهٔ پیشنهادی'):statusName(o.status)}selected.clear();selectedBlocks.clear();fittingFeedback=null;stateNeedsRefresh=true;render();shell.status('آخرین تغییر برنامه برگشت؛ برای تغییر قبلی دوباره بازگشت را بزنید.')}catch(e){if(e.warnings?.length&&window.confirm(e.warnings.map(w=>w.message+' '+validationContext(w)).join('\n')+'\nبا وجود هشدارها بازگشت انجام شود؟'))return undoPlanning({confirmWarnings:true,warningIds:e.warnings.map(w=>w.id)});shell.status(e.message);if(!e.warnings?.length)window.alert(e.message);if(button)button.disabled=false}}
