let groupSelection=false,pendingCrmWarning=true;try{pendingCrmWarning=localStorage.getItem('resourceplanning-pending-crm-warning')!=='off'}catch{}
const $=id=>document.getElementById(id),shell=window.combineShell,dialog=$('dp-dialog')
let dragScrollFrame=0,dragPointerY=0,dragActive=false
let collapsedGroups=new Set(),demandKind='',demandStage='',demandStatus='',demandProjectStatus=['In progress','In Progress - Switched'],info=null,state=null,view='matrix',filters={},from='',to='',selected=new Set(),selectedBlocks=new Set(),archiveWeek='',stateNeedsRefresh=false,jobId=null,busy=false,checking=false,connectionCheck=null,lastFocus=null,demandMode='all',importMode='all',viewCatalog=[],viewCatalogLoaded=false
const btn=(title,attrs='',primary=false)=>`<button type="button" class="ui-button ${primary?'ui-button--primary':''}" ${attrs}>${title}</button>`
const input=(id,label,value='',attrs='')=>`<label class="ui-field" for="${id}">${label}<input class="ui-input" id="${id}" name="${id}" value="${esc(value)}" ${attrs}></label>`
const options=(rows,value,blank='انتخاب کنید')=>`<option value="">${blank}</option>`+rows.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('')
const select=(id,label,rows,value='',blank)=>`<label class="ui-field" for="${id}">${label}<select class="ui-input" id="${id}" name="${id}">${options(rows,value,blank)}</select></label>`
const dateField=(id,label,value='')=>`<label class="ui-field" for="${id}-picker">${label}<input type="hidden" id="${id}" value="${esc(value)}"><button type="button" class="ui-button dp-date-button" id="${id}-picker">انتخاب تاریخ</button></label>`
const check=(id,label,checked=false)=>`<label class="ui-check"><input type="checkbox" id="${id}" ${checked?'checked':''}>${label}</label>`
