async function api(action,body){const response=await fetch('/api/tool-96a847ac/'+action,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'}),data=await response.json();if(response.status===401)location.replace('/login.html');if(!response.ok)throw Object.assign(Error(data.error||'درخواست کامل نشد.'),{status:response.status,warnings:data.warnings,validations:data.validations});return data}
bindLogout({before:()=>{state=null;jobId=null;sessionStorage.removeItem('deploymentplan-job')},onError:m=>shell.status(m)})
async function reload(){const previous=state,value=await api(view==='audit'?'state':'state/compact');if(dialog.open&&dialog.dataset.blockId&&previous){const id=dialog.dataset.blockId,before=previous.allocations.find(a=>a.blockId===id),after=value.allocations.find(a=>a.blockId===id);if(JSON.stringify(before)===JSON.stringify(after))dialog.dataset.revision=String(value.revision)}state=value;stateNeedsRefresh=false;if(!from){const current=startWeek(state.today);from=add(current,-13*7);to=add(current,52*7+6);pendingFocusWeek=current}selected=new Set([...selected].filter(id=>state.allocations.some(a=>a.id===id)));selectedBlocks=new Set([...selectedBlocks].filter(id=>state.blocks.some(b=>b.id===id)));render();paintSettings()}
function mountDates(ids){if(ids.length)mountPersianDatePicker(ids)}
function closeDialog(){dialog.close();lastFocus?.focus()}
$('dp-dialog-close').onclick=closeDialog
dialog.addEventListener('close',()=>{for(const d of document.querySelectorAll('.persian-date-dialog[data-form-picker]'))d.remove();lastFocus?.focus()})
function modal(title,html){hideCardTooltip();dialog.classList.remove('dp-allocation-dialog');lastFocus=document.activeElement;if(dialog.open)dialog.close();$('dp-dialog-title').textContent=title;$('dp-dialog-body').innerHTML=html;$('dp-dialog-error').textContent='';dialog.dataset.revision=String(state.revision);delete dialog.dataset.blockId;dialog.dataset.warningIds='[]';dialog.dataset.confirmWarnings='false';dialog.showModal();const dateIds=[...dialog.querySelectorAll('input[type=hidden]')].filter(n=>$(n.id+'-picker')).map(n=>n.id),before=new Set(document.querySelectorAll('.persian-date-dialog'));mountDates(dateIds);for(const d of document.querySelectorAll('.persian-date-dialog'))if(!before.has(d))d.dataset.formPicker='true';bindContent(dialog)}
function formModal(title,html,onSubmit,{topActions=false}={}){const actions='<div class="ui-dialog-footer dp-form-actions"><button type="button" class="ui-button" id="dp-cancel">انصراف</button><button class="ui-button ui-button--primary" id="dp-submit">ذخیره</button></div>';modal(title,`<form id="dp-form">${topActions?actions:''}${html}${html.includes('dp-warning-details')?'':warningFields()}${topActions?'':actions}</form>`);if(topActions)dialog.classList.add('dp-allocation-dialog');$('dp-cancel').onclick=closeDialog;$('dp-form').onsubmit=async e=>{e.preventDefault();$('dp-submit').disabled=true;$('dp-dialog-error').textContent='';try{const saved=await onSubmit(Number(dialog.dataset.revision));if(saved?.revision)state.revision=saved.revision;closeDialog();if(saved?.result?.remaining&&saved?.result?.allocated){applyFittingResult(saved);return}if(saved?.result?.returnedIds){applyReturnResult(saved);return}const changes=Array.isArray(saved?.result)?saved.result:[saved?.result];if(changes.length&&changes.every(a=>a?.blockId&&a?.id&&a?.days)){for(const allocation of changes){state.allocations=state.allocations.filter(a=>a.id!==allocation.id&&a.blockId!==allocation.blockId).concat(allocation);const o=state.obligations[allocation.obligationId],assigned=state.allocations.filter(a=>a.obligationId===allocation.obligationId).reduce((n,a)=>n+a.days.reduce((m,d)=>m+d.units,0),0);if(o){state.coverage[o.id]={required:o.sizeUnits,assigned,missing:o.sizeUnits==null?null:Math.max(0,o.sizeUnits-assigned),excess:o.sizeUnits==null?null:Math.max(0,assigned-o.sizeUnits)};o.displayStatus=state.coverage[o.id].missing===0&&state.allocations.filter(a=>a.obligationId===o.id).every(a=>a.status==='confirmed')?'برنامهٔ قطعی':'دارای برنامهٔ پیشنهادی'}}stateNeedsRefresh=true;render();shell.status(changes.every(a=>a.status==='confirmed')?'تخصیص‌های انتخاب‌شده قطعی شدند؛ مهر تیک نمایش داده می‌شود.':'تخصیص ذخیره شد.');return}shell.status('ذخیره شد؛ نمایش در حال به‌روزرسانی است.');void reload().then(()=>shell.status('تغییر با موفقیت ذخیره شد.')).catch(err=>shell.status('ذخیره انجام شد؛ تازه‌سازی نمایش ناموفق بود: '+err.message))}catch(e){showValidationError(e);if(e.warnings?.length&&window.confirm('این تغییر هشدار دارد:\n\n'+e.warnings.map(w=>(w.message||w.type)+'\n'+validationContext(w)).join('\n\n')+'\n\nبا وجود این هشدارها ذخیره شود؟')){dialog.dataset.confirmWarnings='true';setTimeout(()=>$('dp-form')?.requestSubmit(),0)}}finally{if($('dp-submit'))$('dp-submit').disabled=false}}}
function showValidationError(e){dialog.dataset.confirmWarnings='false';$('dp-dialog-error').textContent=e.warnings?.length?'ذخیره انجام نشد؛ هشدارها را در پنجرهٔ تأیید بررسی کنید. با ذخیرهٔ دوباره، پنجرهٔ تأیید نمایش داده می‌شود.':e.message;if((e.validations||e.warnings)&&$('dp-action-warnings')){$('dp-warning-details')?.setAttribute('open','');$('dp-action-warnings').innerHTML='<ul>'+(e.validations||e.warnings).map(w=>'<li class="dp-validation-'+(w.mode==='block'?'block':'warn')+'"><strong>'+(w.mode==='block'?'جلوگیری: ':'هشدار: ')+esc(w.type)+'</strong> · '+esc(w.customer)+'<p>'+esc(w.message||conflictDescription(w))+'</p><p>'+esc(validationContext(w))+'</p></li>').join('')+'</ul>';dialog.dataset.warningIds=JSON.stringify((e.warnings||[]).map(w=>w.id));if($('f-warnings')){$('f-warnings').checked=false;$('f-warnings').disabled=!(e.warnings?.length)}}}
async function command(action,data,revision=state.revision){const saved=await api('command',{action,data:dialog.open?{...warningData(),...data}:data,revision});if(saved.undoToken)planningUndoTokens.push(saved.undoToken);if(saved.validationIssues)state.validationIssues=saved.validationIssues;return saved}
function validationContext(w){const d=w.details||{};return [projectOrderContext(state,w)||d.context||'',d.reference?'هفتهٔ CRM: '+fmt(d.reference):'',d.weeks?'هفته‌های تخصیص: '+d.weeks.map(fmt).join('، '):'',d.switch?'سوئیچ مؤثر: '+fmt(d.switch):'',d.completion?'پایان کانورت: '+fmt(d.completion):'',d.days?'روزهای خارج از تقویم معمول: '+d.days.map(fmt).join('، '):'',d.absenceIds?'عدم دسترسی: '+state.absences.filter(a=>d.absenceIds.includes(a.id)).map(a=>a.type+' '+fmt(a.from)+' تا '+fmt(a.to)).join('، '):'',d.syncStart?'بازهٔ سینک: '+fmt(d.syncStart)+' تا '+fmt(d.syncEnd):'',d.earlierWeek?'هفتهٔ زودتر CRM: '+fmt(d.earlierWeek)+'؛ شروع تخصیص: '+fmt(d.earlierStart):'',d.laterWeek?'هفتهٔ دیرتر CRM: '+fmt(d.laterWeek)+'؛ شروع تخصیص: '+fmt(d.laterStart):''].filter(Boolean).join(' · ')}
function warningFields(){return '<details id="dp-warning-details" class="dp-warning-details"><summary>نتیجهٔ اعتبارسنجی‌ها</summary><div id="dp-action-warnings" class="ui-muted" role="status">پیش از ثبت، قواعد فعال پیکربندی کنترل می‌شوند.</div>'+'</details>'}
function warningData(){return {confirmWarnings:dialog.dataset.confirmWarnings==='true',reason:fieldValue('f-reason'),warningIds:JSON.parse(dialog.dataset.warningIds||'[]')}}
function renderFilters(){const rows=Object.values(state.obligations);return `<div class="ui-card dp-filters"><div class="dp-filter-grid">${view==='matrix'?`<div class="dp-week-navigation" role="group" aria-label="پیمایش هفته‌های برنامه">${btn('→','data-matrix-nav="previous" title="بازهٔ قبل" aria-label="بازهٔ قبل"')}${btn('هفتهٔ جاری','data-matrix-nav="today"')}${btn('←','data-matrix-nav="next" title="بازهٔ بعد" aria-label="بازهٔ بعد"')}</div>`:''}${select('filter-kind','گروه',[['Implementation','استقرار'],['Converter','کانورت']],filters.kind,'همه')}${select('filter-expert','کارشناس',state.experts.map(e=>[e.id,e.name]),filters.expert,'همه')}${select('filter-customer','مشتری',unique(rows,'customerId','customer'),filters.customer,'همه')}${select('filter-crm-status','وضعیت بک‌لاگ',[['Planned','برنامه‌ریزی‌شده'],['Request To Plan Sprint','درخواست برنامه‌ریزی'],['Waiting for Customer','در انتظار مشتری'],['Submit','ثبت‌شده']],filters.crmStatus,'همه')}${select('filter-crm-scope','دامنهٔ وضعیت',[['unallocated','فقط تأمین‌نشده'],['all','کل ماتریس']],filters.crmStatusScope||'all')}${select('filter-stage','مرحلهٔ سوئیچ',[['before','قبل از سوئیچ'],['after','بعد از سوئیچ'],['unknown','نامشخص']],filters.stage,'همه')}${check('filter-conflict','فقط دارای تناقض',filters.conflict)}</div><div class="ui-row dp-filter-actions">${btn('اعمال فیلتر','id="dp-apply-filters"',true)}${view==='matrix'?btn('↶','id="dp-undo-planning" title="بازگشت آخرین تغییر برنامه" aria-label="بازگشت آخرین تغییر برنامه" '+(planningUndoTokens.length?'':'disabled')):''}${btn('پاک‌سازی','id="dp-clear-filters"')}</div></div>`}
 function matrixPage(){return renderFilters()+`<div class="dp-quick-filters">${check('dp-quick-confirmed','فقط قطعی‌ها',filters.quickStatus==='confirmed')}${check('dp-quick-proposed','فقط پیشنهادی‌ها',filters.quickStatus==='proposed')}${check('dp-quick-warnings','فقط دارای هشدار',filters.warningsOnly)}${check('dp-quick-crm','منتظر ثبت در CRM',filters.waitingCrm)}${check('dp-group-mode','حالت انتخاب گروهی',groupSelection)}</div>`+`<div class="dp-toolbar"><div class="ui-row dp-selection-actions">${btn('تخصیص گروهی بلوک‌ها ('+num(selectedBlocks.size)+')','id="dp-assign-selected-blocks" '+(selectedBlocks.size?'':'hidden'))}${btn('بازگرداندن انتخاب‌ها','id="dp-return-selected" '+(selected.size?'':'hidden'))}${info.manager?btn('تأیید انتخاب‌ها ('+num(selected.size)+')','id="dp-approve-selected" '+(selected.size?'':'hidden'))+btn('جابه‌جایی انتخاب‌ها','id="dp-move-selected" '+(selected.size?'':'hidden')):''}</div><details class="dp-help"><summary aria-label="راهنمای نمایش بکلاگ‌ها" title="راهنمای نمایش بکلاگ‌ها">؟</summary><div class="dp-help-popover">${displayLegend()}</div></details></div>${fittingFeedbackMarkup()}${matrix(state,{from,to,filters,selected,collapsedGroups,demandKind,demandStage,demandStatus,demandProjectStatus})}<p class="ui-muted">خانهٔ خالی فقط به معنی ثبت‌نشدن برنامه است. برای انتخاب چند تخصیص، چک‌باکس کنار بلوک‌ها یا Ctrl+کلیک را استفاده کنید.</p><details class="ui-card" style="margin-top:16px"><summary>تعهدات بدون هفته</summary>${demandList(state,filters,'undated')}</details><details class="ui-card" style="margin-top:12px"><summary>تعهدات عقب‌افتاده و تأمین‌نشده</summary>${demandList(state,filters,'overdue')}</details>`}
function requestsPage(){const rows=state.requests.filter(r=>r.status==='pending');return rows.length?'<div class="dp-list">'+rows.map(r=>{const o=state.obligations[r.before.obligationId],ex=state.experts.find(e=>e.id===r.before.expertId),afterEx=state.experts.find(e=>e.id===r.after?.expertId);return `<article class="dp-record"><div><h3>${esc(o.project)}</h3><p>${esc(o.title)}</p><p>برنامهٔ معتبر: ${esc(ex?.name)}، ${fmt(r.before.days[0].date)} تا ${fmt(r.before.days.at(-1).date)}</p><p>پیشنهاد: ${r.after?esc(afterEx?.name)+'، '+fmt(r.after.days[0].date)+' تا '+fmt(r.after.days.at(-1).date):'حذف تخصیص'}</p><p>درخواست‌کننده: ${esc(r.actor.name)} · ${instant(r.at)}</p></div><div class="ui-row">${info.manager?btn('تأیید تغییر',`data-review="${esc(r.id)}" data-decision="approve"`,true)+btn('رد درخواست',`data-review="${esc(r.id)}" data-decision="reject"`):'<span class="dp-label">در انتظار مدیر</span>'}</div></article>`}).join('')+'</div>':'<div class="ui-card dp-empty">پیشنهادی در انتظار تأیید نیست. درخواست تغییر، برنامهٔ قطعی فعلی را تغییر نمی‌دهد.</div>'}
function conflictsPage(){const projects=[...new Map(Object.values(state.obligations).map(o=>[o.projectId,o])).values()];return `<details class="ui-card dp-switch-list"><summary>پلن و سوئیچ پروژه‌ها</summary><div class="dp-list">${projects.map(o=>{const p=state.plans[o.projectId]||{};return `<article class="dp-record"><div><h3>${esc(o.project)}</h3><p>مرجع: ${p.reference?fullDate(p.reference):'نامشخص'} · مؤثر: ${p.effective?fullDate(p.effective):'نامشخص'}</p><p>مرحله: ${{before:'قبل از سوئیچ',after:'بعد از سوئیچ',unknown:'نامشخص'}[p.stage]||'نامشخص'}</p></div>${info.manager?btn('تعیین سوئیچ و رنگ',`data-switch="${esc(o.id)}"`):''}</article>`}).join('')}</div></details><div class="dp-list">${state.conflicts.length?state.conflicts.map(c=>`<article class="dp-record"><div><h3>${esc(c.type)}</h3><p>${esc(c.customer)} · ${esc(c.project)}</p><p>${esc(conflictDescription(c))}</p>${c.exception?`<p>استثنای پذیرفته‌شده: ${esc(c.exception.reason)} · ${esc(c.exception.actor.name)}</p>`:''}</div><div class="ui-row">${c.allocationId?btn('بررسی برنامه',`data-allocation="${esc(c.allocationId)}"`):c.obligationId?btn('بررسی تعهد',`data-obligation="${esc(c.obligationId)}"`):''}${info.manager&&!c.exception?btn('ثبت پذیرش استثنا',`data-exception="${esc(c.id)}"`):''}</div></article>`).join(''):'<div class="ui-card dp-empty">تناقض فعالی در داده‌های قابل مشاهده وجود ندارد.</div>'}</div>`}
function conflictDescription(c){const d=c.details;if(d.message)return d.message;if(d.required!==undefined)return 'نیاز '+num(d.required/2)+'، پوشش برنامه '+num(d.assigned/2)+' نفرروز';if(d.reference!==undefined)return 'مرجع: '+(d.reference?fmt(d.reference):'بدون هفته')+(d.effective?'؛ مؤثر: '+fmt(d.effective):'');if(d.status)return 'وضعیت CRM: '+statusName(d.status);if(d.sprint)return 'Sprint Time: '+fmt(d.sprint)+'؛ BacklogDate: '+fmt(d.backlog);return 'مقادیر مرجع و برنامهٔ محلی را در جزئیات بررسی کنید.'}
 function expertsPage(){return `<div class="dp-toolbar"><p class="ui-muted">کارشناسان فعال در ماتریس نمایش داده می‌شوند. برداشتن کارشناس از فهرست فعال، سابقهٔ برنامه‌های او را حفظ می‌کند.</p><div class="ui-row">${info.manager?btn('افزودن کارشناس استقرار یا کانورت','id="dp-add-expert"',true):''}${btn('ثبت عدم دسترسی','id="dp-add-absence"')}</div></div><input id="dp-expert-search" class="ui-input" type="search" placeholder="جست‌وجوی نام کارشناس" aria-label="جست‌وجوی نام کارشناس"><div class="ui-card ui-table-wrap"><table id="dp-experts-table" class="dp-table"><thead><tr><th>نام</th><th>گروه</th><th>وضعیت</th><th>ترتیب</th><th>اقدام</th></tr></thead><tbody>${state.experts.slice().sort((a,b)=>Number(b.active)-Number(a.active)||a.order-b.order).map(e=>`<tr><td>${esc(e.name)}</td><td>${typeName(e.kind)}</td><td>${e.active?'فعال':'غیرفعال'}</td><td>${num(e.order)}</td><td>${info.manager?'<div class="ui-row">'+btn('ویرایش',`data-expert="${esc(e.id)}"`)+btn(e.active?'برداشتن از فهرست فعال':'فعال‌کردن دوباره',`data-toggle-expert="${esc(e.id)}"`)+'</div>':'—'}</td></tr>`).join('')||'<tr><td colspan="5">هنوز کارشناسی تعریف نشده است.</td></tr>'}</tbody></table></div><h2 style="margin:24px 0 12px">عدم دسترسی‌ها</h2><div class="dp-list">${state.absences.map(a=>`<article class="dp-record"><div><h3>${esc(state.experts.find(e=>e.id===a.expertId)?.name)} · ${esc(a.type)}</h3><p>${fullDate(a.from)} تا ${fullDate(a.to)}</p><p>${esc(a.note)}</p></div>${startWeek(a.from)>=startWeek(state.today)?btn('ویرایش',`data-absence="${esc(a.id)}"`):'<span class="dp-label">آرشیو</span>'}</article>`).join('')||'<p class="ui-muted">عدم دسترسی ثبت نشده است.</p>'}</div>`}
function archivePage(){const ws=Object.keys(state.archives).sort().reverse();archiveWeek=ws.includes(archiveWeek)?archiveWeek:ws[0]||'';if(!archiveWeek)return '<div class="ui-card dp-empty">هنوز هفته‌ای آرشیو نشده است. پایان هفته، تصویر برنامه به‌صورت خودکار و فقط‌خواندنی حفظ می‌شود.</div>';const a=state.archives[archiveWeek],snapshot={...state,...a,plans:a.plans,colors:a.colors,conflicts:[]};return `<div class="dp-toolbar">${select('dp-archive-week','هفتهٔ آرشیو',ws.map(w=>[w,fmt(w)+' تا '+fmt(add(w,6))]),archiveWeek)}<span class="ui-muted">ثبت آرشیو: ${instant(a.at)}</span></div><div class="dp-archive-note">این تصویر فقط‌خواندنی است؛ گذشت هفته به معنی انجام واقعی کار نیست.</div>${renderFilters()}${matrix(snapshot,{from:archiveWeek,to:add(archiveWeek,6),filters,readonly:true,collapsedGroups})}`}
function auditPage(){return '<div class="dp-list">'+state.audit.slice().reverse().map(a=>`<details class="ui-card"><summary>${esc(a.action)} · ${esc(a.actor.name)} · ${instant(a.at)}</summary><div class="dp-form-grid"><div><h3>قبل از تغییر</h3><pre class="dp-audit">${esc(JSON.stringify(a.before,null,2))}</pre></div><div><h3>بعد از تغییر</h3><pre class="dp-audit">${esc(JSON.stringify(a.after,null,2))}</pre></div></div></details>`).join('')+'</div>'}
function viewRows(query=''){const list=$('s-view-selected');if(!list)return;const saved=state.settings.crmView,selected=list.value||(saved?.id?saved.type+':'+saved.id:''),term=query.trim().toLocaleLowerCase('fa');const rows=viewCatalog.filter(v=>v.name.toLocaleLowerCase('fa').includes(term)||v.type+':'+v.id===selected);list.replaceChildren(new Option('View را انتخاب کنید',''),...rows.map(v=>new Option(v.name+' · '+(v.type==='system'?'عمومی':'شخصی'),v.type+':'+v.id)));if(selected&&!rows.some(v=>v.type+':'+v.id===selected))list.add(new Option(state.settings.crmViewName||'ویوی ذخیره‌شده',selected));list.value=selected}

function validationSettingsPage(){const texts={beforeSync:'استقرار قبل از سوئیچ، پیش از سینک نهایی باشد',afterSync:'استقرار بعد از سوئیچ، پس از سینک نهایی باشد',referenceOrder:'بکلاگ هفتهٔ بعد، به هفته‌ای زودتر از بکلاگ قبلی منتقل نشود؛ همان هفته مجاز است',crmWeek:'هفتهٔ تخصیص با هفتهٔ مرجع CRM متفاوت باشد',expertOverlap:'مجموع استقرار کارشناس بیشتر از ۵ نفرروز در هفته باشد',absenceOverlap:'برنامه با مرخصی یا عدم دسترسی تداخل داشته باشد',nonWorkingDay:'استقرار در پنجشنبه یا جمعه باشد',conversionDeadline:'کانورت بعد از سوئیچ مؤثر تمام شود',unknownStage:'مرحله یا مرجع سینک نامشخص باشد',projectPriority:'ترتیب اولویت‌های CRM بین هفته‌ها رعایت نشود؛ همان هفته مجاز است'};return '<form id="dp-validation-form" class="ui-card dp-validation-settings"><div class="ui-row ui-between"><h2>قواعد برنامه‌ریزی</h2>'+(info.manager?'<button class="ui-button ui-button--primary" type="submit">ذخیرهٔ قواعد</button>':'')+'</div><p class="ui-muted">هشدار با تأیید قابل ادامه است؛ جلوگیری اجازهٔ ذخیره نمی‌دهد.</p><table class="dp-table dp-rules-table"><thead><tr><th>قاعده</th><th>حالت</th></tr></thead><tbody>'+(state.validationRules||[]).map(r=>'<tr><td>'+esc(texts[r.id]||r.description)+'</td><td>'+select('rule-'+r.id,'', [['off','خاموش'],['warn','هشدار'],['block','جلوگیری']],state.settings.validationPolicies[r.id]||r.defaultMode)+'</td></tr>').join('')+'</tbody></table><p id="dp-validation-error" class="dp-error"></p><p id="dp-validation-saved" role="status"></p></form>'}

function settingsPage(){const v=state.settings,selected=v.crmView?.id?`${v.crmView.type}:${v.crmView.id}`:'',intervals=[5,15,30,60,120,240,720,1440];if(!intervals.includes(v.intervalMinutes))intervals.push(v.intervalMinutes);intervals.sort((a,b)=>a-b);return validationSettingsPage()+`<div class="dp-display-option">${check('dp-pending-crm-warning','نمایش هشدار «قطعی شده، اما وضعیت CRM هنوز درخواست برنامه‌ریزی است»',pendingCrmWarning)}<p class="ui-muted">این گزینه فقط نمایش و فیلتر را تغییر می‌دهد؛ قواعد ذخیره و اطلاعات CRM تغییر نمی‌کنند. انتخاب در این مرورگر ذخیره می‌شود.</p></div><form id="dp-settings-form" class="ui-card dp-view-settings"><h2>تعهدات استقرار و کانورت</h2><label class="ui-field" for="s-view-selected">View اصلی از کیس‌های CRM</label><input class="ui-input" id="dp-view-search" type="search" placeholder="جستجو در نام ویوها" aria-label="جستجو در نام ویوهای Case" autocomplete="off"><select class="ui-input" id="s-view-selected" required><option value="">View را انتخاب کنید</option>${selected?`<option value="${esc(selected)}" selected>${esc(v.crmViewName||"ویوی ذخیره‌شده")}</option>`:""}</select><div class="dp-view-list-footer"><span id="dp-view-check-result" class="ui-muted" role="status">برای تغییر View، فهرست CRM دریافت می‌شود.</span>${btn('به‌روزرسانی فهرست','id="dp-load-views"')}</div>${select('s-interval','فاصلهٔ دریافت خودکار',intervals.map(n=>[n,n<60?n+' دقیقه':n%60===0?n/60+' ساعت':n+' دقیقه']),v.intervalMinutes)}${check('s-periodic','دریافت خودکار فعال باشد',v.periodic)}<div class="dp-view-save">${info.manager?'<button class="ui-button ui-button--primary">ذخیرهٔ تنظیمات</button>':'<p>تغییر تنظیمات فقط برای مدیر ابزار مجاز است.</p>'}<p id="dp-settings-error" role="alert" class="dp-error"></p></div><p class="ui-muted">آخرین دریافت: ${instant(state.lastSync?.at)}</p></form>`}

