 const draw=()=>{frame=0;if(!active)return;const a=active;if(!a.started&&Math.hypot(a.x-a.startX,a.y-a.startY)<5)return;a.started=true;const bounds=wrap.getBoundingClientRect(),edge=38,speed=a.y<bounds.top+edge?-12:a.y>bounds.bottom-edge?12:0;if(speed)wrap.scrollTop+=speed;const originY=a.startY-(wrap.scrollTop-a.startScroll);const hitTop=Math.min(originY,a.y),hitBottom=Math.max(originY,a.y);const left=Math.max(bounds.left,Math.min(a.startX,a.x)),right=Math.min(bounds.right,Math.max(a.startX,a.x)),top=Math.max(bounds.top,Math.min(originY,a.y)),bottom=Math.min(bounds.bottom,Math.max(originY,a.y));if(!box){box=document.createElement('div');box.className='dp-selection-box';document.body.append(box)}Object.assign(box.style,{left:left+'px',top:top+'px',width:Math.max(0,right-left)+'px',height:Math.max(0,bottom-top)+'px'});selected=new Set(a.add?a.planned:[]);selectedBlocks=new Set(a.add?a.blocks:[]);wrap.querySelectorAll('.dp-card[data-block],.dp-card[data-allocation]').forEach(n=>{const r=n.getBoundingClientRect();if(r.right>left&&r.left<right&&r.bottom>hitTop&&r.top<hitBottom){if(n.dataset.block)selectedBlocks.add(n.dataset.block);else selected.add(n.dataset.allocation)}});sync();if(speed)frame=requestAnimationFrame(draw)};
 const down=e=>{if(e.button!==0||e.target.closest('button,input,a,select,textarea,th')||!e.target.closest('td'))return;active={startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,planned:[...selected],blocks:[...selectedBlocks],startScroll:wrap.scrollTop,add:e.ctrlKey||e.metaKey,started:false,pointerId:e.pointerId};wrap.setPointerCapture(e.pointerId);e.preventDefault()};
