 const fit=()=>{cancelAnimationFrame(fitFrame);fitFrame=requestAnimationFrame(()=>fitCardTitles($('tool-content')))};
 if(!bottom){fit();document.fonts.ready.then(fit);return}
 const table=bottom.querySelector('table'),frame=bottom.parentElement;let initialized=false;const help=document.querySelector('.dp-toolbar>.dp-help'),actions=document.querySelector('.dp-filter-actions');if(help&&actions){actions.append(help)}
 const rail=document.createElement('div'),spacer=document.createElement('div');rail.className='dp-bottom-scroll';rail.tabIndex=0;rail.setAttribute('aria-label','پیمایش افقی هفته‌های برنامه');rail.append(spacer);const thumb=document.createElement('div');thumb.className='dp-scroll-thumb';rail.append(thumb);rail.setAttribute('role','scrollbar');rail.setAttribute('aria-orientation','horizontal');rail.setAttribute('aria-valuemin','0');document.body.append(rail);const cleanupBox=bindBoxSelection(bottom);const paintThumb=()=>{const max=Math.max(0,bottom.scrollWidth-bottom.clientWidth),width=Math.max(36,rail.clientWidth*bottom.clientWidth/Math.max(1,bottom.scrollWidth)),travel=Math.max(0,rail.clientWidth-width);thumb.style.width=width+'px';thumb.style.left=(max?bottom.scrollLeft/max*travel:0)+'px';rail.setAttribute('aria-valuemax',String(max));rail.setAttribute('aria-valuenow',String(Math.round(bottom.scrollLeft)))};let thumbDrag=null;rail.onpointerdown=e=>{if(e.button!==0)return;const max=Math.max(0,bottom.scrollWidth-bottom.clientWidth),travel=rail.clientWidth-thumb.getBoundingClientRect().width;if(e.target!==thumb&&travel>0){const pos=e.clientX-rail.getBoundingClientRect().left-thumb.getBoundingClientRect().width/2;bottom.scrollLeft=Math.max(0,Math.min(max,pos/travel*max))}thumbDrag={x:e.clientX,left:bottom.scrollLeft};rail.setPointerCapture(e.pointerId);e.preventDefault()};rail.onpointermove=e=>{if(!thumbDrag)return;const travel=rail.clientWidth-thumb.getBoundingClientRect().width;if(travel>0)bottom.scrollLeft=thumbDrag.left+(e.clientX-thumbDrag.x)/travel*(bottom.scrollWidth-bottom.clientWidth);syncFromTable()};rail.onpointerup=rail.onpointercancel=()=>{thumbDrag=null};rail.onwheel=e=>{e.preventDefault();bottom.scrollLeft+=e.deltaX||e.deltaY;syncFromTable()};rail.onkeydown=e=>{const step=e.key==='ArrowLeft'?-80:e.key==='ArrowRight'?80:0;if(step){e.preventDefault();bottom.scrollLeft+=step;syncFromTable()}};
