async function sync(mode='manual'){if(busy)return;busy=true;$('dp-sync').disabled=true;try{const job=await api('sync',{mode});if(job.state==='disabled'){busy=false;$('dp-sync').disabled=false;return}jobId=job.id;sessionStorage.setItem('deploymentplan-job',jobId);await pollJob()}catch(e){busy=false;$('dp-sync').disabled=false;shell.status(e.message)}}
async function pollJob(){if(!jobId)return;try{const job=await api('job?id='+encodeURIComponent(jobId));shell.status(job.message);if(job.state==='running'){setTimeout(pollJob,1500);return}jobId=null;sessionStorage.removeItem('deploymentplan-job');busy=false;$('dp-sync').disabled=false;if(job.state==='success')await reload()}catch(e){jobId=null;busy=false;sessionStorage.removeItem('deploymentplan-job');$('dp-sync').disabled=false;shell.status(e.message)}}
